import { words as getWords } from './words.ts';

/**
 * Converts the first character of each word in a string to uppercase and the remaining characters to lowercase.
 *
 * Start case is the naming convention in which each word is written with an initial capital letter.
 * @param str - The string to convert.
 * @returns The converted string.
 *
 * @example
 * const result1 = startCase('hello world');  // result will be 'Hello World'
 * const result2 = startCase('HELLO WORLD');  // result will be 'Hello World'
 * const result3 = startCase('hello-world');  // result will be 'Hello World'
 * const result4 = startCase('hello_world');  // result will be 'Hello World'
 * @guarantee ok.capitalized-words "hello world" gives "Hello World" and "HELLO WORLD" gives "Hello World"
 * @guarantee ok.from-camel-pascal "fooBar" gives "Foo Bar" and "PascalCase" gives "Pascal Case"
 * @guarantee ok.hyphen-underscore "hello-world" gives "Hello World" and "hello_world" gives "Hello World"
 * @guarantee ok.delimiters-trimmed "--foo-bar--" gives "Foo Bar" and "__FOO_BAR__" gives "Foo Bar"
 * @guarantee ok.acronym-and-numbers "XMLHttpRequest" gives "Xml Http Request", "_abc_123_def" gives "Abc 123 Def" and "12abc 12ABC" gives "12 Abc 12 Abc"
 * @guarantee ok.only-delimiters-empty "_-_-_-_" gives ""
 */
export function startCase(str: string): string {
  const words = getWords(str.trim());
  let result = '';
  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (result) {
      result += ' ';
    }

    result += word[0].toUpperCase() + word.slice(1).toLowerCase();
  }
  return result;
}

